<script>
	$(document).ready(function() {
		
		$(function(){
			$(\'.quantity, .comis, .vatki\').each(function() {
				var elem = $(this);
				elem.bind("propertychange change keyup input paste", function(event){
					[[calculator]]
					var o=$(this.parentNode.parentNode);
					var price = o.find(\'.quantity\').val();
					var comis = o.find(\'.comis\').val();
					var vatki = o.find(\'.vatki\').val();

					if ( price != \'\') {
						console.log(6)
						$(".calculator").each( function () {
							var comissia = price * comis;
							if (comissia<29) {
								comissia = 29;
							}
							var kuznia = +price + +comissia;
							var vat = kuznia / vatki;
							var ostatok = kuznia - vat;
							var finalprice = kuznia - ostatok;

							//var plnconvert = pln * finalprice;
							//var usdconvert = plnconvert / usd;

							var kuzniaBYR = pln * kuznia;
							var comissiaBYR = pln * comissia;
							var ostatokBYR = pln * ostatok;
							var finalpriceBYR = pln * finalprice;

							$(\'.comission\').val(comissia.toFixed(2));
							$(\'.oplata\').val(kuznia.toFixed(2));
							$(\'.vat\').val(ostatok.toFixed(2));
							finalprice += +(parseFloat($(this).val())||0).toFixed(2);
							$(\'.final\').val(finalprice.toFixed(2));

							$( "#BYR" ).click(function(e) {
								e.preventDefault();
								$(\'.comission\').val(comissiaBYR.toFixed(2));
								$(\'.oplata\').val(kuzniaBYR.toFixed(2));
								$(\'.vat\').val(ostatokBYR.toFixed(2));
								$(\'.final\').val(finalpriceBYR.toFixed(2));
								
								$(\'.corrency\').text($(this).text());
								$(\'#BYR\').css(\'background\', \'#5b8f00\');
								$(\'#PLN\').css(\'background\', \'#f1c40f\');
								$(\'#usd\').css(\'background\', \'#f1c40f\');
							});

							$( "#PLN" ).click(function(e) {
								e.preventDefault();
								comissia = comissiaBYR / pln;
								$(\'.comission\').val(comissia.toFixed(2));
								kuznia = kuzniaBYR / pln;
								$(\'.oplata\').val(kuznia.toFixed(2));
								ostatok = ostatokBYR / pln;
								$(\'.vat\').val(ostatok.toFixed(2));
								finalprice = finalpriceBYR / pln;
								$(\'.final\').val(finalprice.toFixed(2));
								
								$(\'.corrency\').text(\'ZL\');
								$(\'#PLN\').css(\'background\', \'#5b8f00\');
								$(\'#BYR\').css(\'background\', \'#f1c40f\');
								$(\'#usd\').css(\'background\', \'#f1c40f\');
							});

							$( "#usd" ).click(function(e) {
								e.preventDefault();
								comissia = comissiaBYR / usd;
								$(\'.comission\').val(comissia.toFixed(2));
								kuznia = kuzniaBYR / usd;
								$(\'.oplata\').val(kuznia.toFixed(2));
								ostatok = ostatokBYR / usd;
								$(\'.vat\').val(ostatok.toFixed(2));
								finalprice = finalpriceBYR / usd;
								$(\'.final\').val(finalprice.toFixed(2));
								
								$(\'.corrency\').text($(this).text());
								$(\'#usd\').css(\'background\', \'#5b8f00\');
								$(\'#BYR\').css(\'background\', \'#f1c40f\');
								$(\'#PLN\').css(\'background\', \'#f1c40f\');
							});
						});
					}

				});
			});
		});
	});
</script>
` ]]

